Section KIdx.
Variables (s nc kx minv maxv : Z) (ncv : Z -> Z) (M0 : word -> option byte).
Definition RK : list (Z * Z) := [(kx, 1024%Z)].
Hypothesis GEO : (4096 <= s - 272 /\ s <= 2 ^ 47 /\ 4096 <= nc /\ nc + 40 <= 2 ^ 47 /\ 4096 <= kx /\ kx + 1024 <= 2 ^ 47 /\
                  (kx + 1024 <= nc \/ nc + 40 <= kx) /\ (kx + 1024 <= s - 272 \/ s <= kx) /\ kx mod 4 = 0 /\
                  0 <= minv <= 255 /\ 0 <= maxv <= 255)%Z.
Hypothesis NCV : forall j, (0 <= j < 10)%Z -> (0 <= ncv j <= 255)%Z.
Hypothesis SOK : store_ok SEGS M0 (Z_to_bv 64 kx) 1024 = true.
Hypothesis Cmin : rdn SEGS M0 (Z_to_bv 64 (s - 148)) 4 = Some (Z_to_le_bytes 4 minv).
Hypothesis Cmax : rdn SEGS M0 (Z_to_bv 64 (s - 152)) 4 = Some (Z_to_le_bytes 4 maxv).
Hypothesis Cncomps : rdn SEGS M0 (Z_to_bv 64 (s - 216)) 8 = Some (Z_to_le_bytes 8 10).
Hypothesis Cnc : forall j, (0 <= j < 10)%Z -> rdn SEGS M0 (Z_to_bv 64 (nc + 4 * j)) 4 = Some (Z_to_le_bytes 4 (ncv j)).

Ltac geo := pose proof GEO as (Gs & Gs47 & Gnc & Gnc2 & Gkx & Gkx2 & APn & APs & Akx & Gmin & Gmax).

