(* [comment removed for export] *)
Definition kidx_regs (regs : bvmap 5 word) (i k : Z) : Prop :=
  getr regs 2 = Z_to_bv 64 (s - 272) /\ getr regs 10 = Z_to_bv 64 kx /\ getr regs 11 = Z_to_bv 64 i /\ getr regs 14 = Z_to_bv 64 k /\
  getr regs 26 = Z_to_bv 64 nc /\ getr regs 8 = Z_to_bv 64 9.

(* [comment removed for export] *)
Lemma kidx_inner : forall (j : nat) fr cs regs (M : word -> option byte) (i n k : Z),
  Z.of_nat j = (n - i)%Z -> (0 <= i < n)%Z -> (n <= 255)%Z -> (0 <= k <= 8)%Z -> frm_zero cs -> rinv RK M0 M -> kidx_ok M ->
  fpv_read fr FMT_S 15 = cvS n -> kidx_regs regs i k -> getr regs 12 = Z_to_bv 64 (kx + 4 * i) ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2da2c : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2da44 : word) M' rom /\ frm_zero cs' /\ rinv RK M0 M' /\ kidx_ok M' /\
                kidx_regs regs' n k /\ regs_agree (fun r => In r [11; 12; 15]%list) regs regs' /\
                (forall r : reg, r <> 14%bv -> reg_get fr' r = reg_get fr r)).
Proof.
