(* [comment removed for export] *)
Definition KL : list reg := [11; 12; 13; 14; 15]%bv.
Definition kidx_post958 (fr0 : bvmap 5 word) (regs0 : bvmap 5 word) (fin : machine_state) : Prop :=
  exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2da54 : word) M' rom /\ frm_zero cs' /\ rinv RK M0 M' /\ kidx_ok M' /\
    getr regs' 12 = Z_to_bv 64 maxv /\ regs_agree (fun r => In r KL) regs0 regs' /\
    (forall r : reg, r <> 14%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr0 r).

(* [comment removed for export] *)
Lemma kidx_latch : forall fr0 regs0 fr cs regs (M : word -> option byte) (i k : Z),
  (0 <= k <= 8)%Z -> (0 <= i <= 255)%Z -> frm_zero cs -> rinv RK M0 M -> kidx_ok M ->
  getr regs 2 = Z_to_bv 64 (s - 272) -> getr regs 10 = Z_to_bv 64 kx -> getr regs 11 = Z_to_bv 64 i -> getr regs 13 = Z_to_bv 64 (k + 1) ->
  getr regs 26 = Z_to_bv 64 nc -> getr regs 8 = Z_to_bv 64 9 -> getr regs 12 = Z_to_bv 64 maxv ->
  regs_agree (fun r => In r KL) regs0 regs -> (forall r : reg, r <> 14%bv -> r <> 15%bv -> reg_get fr r = reg_get fr0 r) ->
  ((k + 1 < 9)%Z -> (i <= maxv)%Z -> forall regs1, kidx_regs regs1 i (k + 1) -> getr regs1 12 = Z_to_bv 64 maxv -> regs_agree (fun r => In r KL) regs0 regs1 ->
      reach SEGS (@mkst (mkFP fr cs) regs1 (0x2da04 : word) M rom) (kidx_post958 fr0 regs0)) ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2da48 : word) M rom) (kidx_post958 fr0 regs0).
