Lemma kidx_seg : forall fr cs regs,
  frm_zero cs -> kidx_ok M0 ->
  getr regs 2 = Z_to_bv 64 (s - 272) -> getr regs 10 = Z_to_bv 64 kx -> getr regs 26 = Z_to_bv 64 nc -> getr regs 8 = Z_to_bv 64 9 ->
