(* [comment removed for export] *)
Section KFr.
Variables (s nc kf minv maxv bord : Z) (ncv : Z -> Z) (M0 : word -> option byte).
Definition RF : list (Z * Z) := [(kf, 1024%Z)].
Hypothesis GEO : (4096 <= s - 272 /\ s <= 2 ^ 47 /\ 4096 <= nc /\ nc + 40 <= 2 ^ 47 /\ 4096 <= kf /\ kf + 1024 <= 2 ^ 47 /\
                  (kf + 1024 <= nc \/ nc + 40 <= kf) /\ (kf + 1024 <= s - 272 \/ s <= kf) /\ kf mod 4 = 0 /\
                  0 <= minv <= 255 /\ 0 <= maxv <= 255 /\ 0 <= bord < 2 ^ 63)%Z.
Hypothesis NCV : forall j, (0 <= j < 10)%Z -> (0 <= ncv j <= 255)%Z.
Hypothesis SOK : store_ok SEGS M0 (Z_to_bv 64 kf) 1024 = true.
Hypothesis Cmin : rdn SEGS M0 (Z_to_bv 64 (s - 148)) 4 = Some (Z_to_le_bytes 4 minv).
Hypothesis Cmax : rdn SEGS M0 (Z_to_bv 64 (s - 152)) 4 = Some (Z_to_le_bytes 4 maxv).
Hypothesis Cbord : rdn SEGS M0 (Z_to_bv 64 (s - 184)) 8 = Some (Z_to_le_bytes 8 bord).
Hypothesis Cnc : forall j, (0 <= j < 10)%Z -> rdn SEGS M0 (Z_to_bv 64 (nc + 4 * j)) 4 = Some (Z_to_le_bytes 4 (ncv j)).

Ltac geo := pose proof GEO as (Gs & Gs47 & Gnc & Gnc2 & Gkf & Gkf2 & APn & APs & Akf & Gmin & Gmax & Gbord).

Lemma kfr_cell : forall (M : word -> option byte) (a : Z) (n : nat) bs, rinv RF M0 M -> (0 <= a)%Z -> (a + Z.of_nat n <= 2 ^ 64)%Z ->
  (a + Z.of_nat n <= kf \/ kf + 1024 <= a)%Z -> rdn SEGS M0 (Z_to_bv 64 a) n = Some bs -> rdn SEGS M (Z_to_bv 64 a) n = Some bs.
Proof.
