Definition kfr_regs (regs : bvmap 5 word) (i k : Z) : Prop :=
  getr regs 2 = Z_to_bv 64 (s - 272) /\ getr regs 10 = Z_to_bv 64 kf /\ getr regs 12 = Z_to_bv 64 i /\ getr regs 13 = Z_to_bv 64 k /\
  getr regs 26 = Z_to_bv 64 nc /\ getr regs 8 = Z_to_bv 64 9 /\ getr regs 11 = Z_to_bv 64 maxv /\ getr regs 17 = Z_to_bv 64 bord.

Definition FL : list reg := [12; 13; 14; 15; 16]%bv.
(* [comment removed for export] *)
Definition kfr_fp (fr fr' : bvmap 5 word) : Prop := forall r : reg, r <> 12%bv -> r <> 13%bv -> r <> 14%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr r.

(* [comment removed for export] *)
Lemma kfr_inner : forall (j : nat) fr cs regs (M : word -> option byte) (i n k : Z),
  Z.of_nat j = (n - i)%Z -> (0 <= i < n)%Z -> (n <= 255)%Z -> frm_zero cs -> rinv RF M0 M ->
  fpv_read fr FMT_S 15 = cvS n -> kfr_regs regs i k -> getr regs 15 = Z_to_bv 64 (kf + 4 * i) ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2dac0 : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2dae0 : word) M' rom /\ frm_zero cs' /\ rinv RF M0 M' /\
                kfr_regs regs' n k /\ regs_agree (fun r => In r [12; 15; 16]%list) regs regs' /\ kfr_fp fr fr').
