Definition FLL : list reg := [11; 12; 13; 14; 15; 16; 17]%bv.
Definition kfr_post9f0 (fr0 : bvmap 5 word) (regs0 : bvmap 5 word) (fin : machine_state) : Prop :=
  exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2daec : word) M' rom /\ frm_zero cs' /\ rinv RF M0 M' /\
    getr regs' 11 = Z_to_bv 64 maxv /\ getr regs' 17 = Z_to_bv 64 bord /\ regs_agree (fun r => In r FLL) regs0 regs' /\ kfr_fp fr0 fr'.

(* [comment removed for export] *)
Lemma kfr_latch : forall fr0 regs0 fr cs regs (M : word -> option byte) (i k n : Z),
  (0 <= k <= 8)%Z -> (0 <= i <= 255)%Z -> frm_zero cs -> rinv RF M0 M ->
  getr regs 2 = Z_to_bv 64 (s - 272) -> getr regs 10 = Z_to_bv 64 kf -> getr regs 12 = Z_to_bv 64 i -> getr regs 13 = Z_to_bv 64 (k + 1) ->
  getr regs 26 = Z_to_bv 64 nc -> getr regs 8 = Z_to_bv 64 9 -> getr regs 11 = Z_to_bv 64 maxv -> getr regs 17 = Z_to_bv 64 bord ->
  regs_agree (fun r => In r FLL) regs0 regs -> kfr_fp fr0 fr ->
  ((k + 1 < 9)%Z -> (i <= maxv)%Z -> forall regs1, kfr_regs regs1 i (k + 1) -> regs_agree (fun r => In r FLL) regs0 regs1 ->
      reach SEGS (@mkst (mkFP fr cs) regs1 (0x2da90 : word) M rom) (kfr_post9f0 fr0 regs0)) ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2dae0 : word) M rom) (kfr_post9f0 fr0 regs0).
Proof.
