(* [comment removed for export] *)
Lemma kfr_seg : forall fr cs regs,
  frm_zero cs -> getr regs 2 = Z_to_bv 64 (s - 272) -> getr regs 10 = Z_to_bv 64 kf -> getr regs 26 = Z_to_bv 64 nc -> getr regs 8 = Z_to_bv 64 9 ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2da78 : word) M0 rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2dafc : word) M' rom /\ frm_zero cs' /\ rinv RF M0 M' /\
                getr regs' 17 = Z_to_bv 64 bord /\ regs_agree (fun r => In r FLL) regs regs' /\ kfr_fp fr fr').
Proof.
