(* [comment removed for export] *)
(* [comment removed for export] *)
Section SpL.
Variables (s arr n : Z) (M0 : word -> option byte).
Definition R_SpL : list (Z * Z) := [(arr, (4 * n)%Z); ((s - 272 - 16)%Z, 16%Z)].
Hypothesis GEO : (4096 <= s - 272 - 16 /\ s <= 2 ^ 47 /\ 4096 <= arr /\ arr + 4 * n <= 2 ^ 47 /\ 1 <= n <= 65536 /\
                  (arr + 4 * n <= s - 272 - 16 \/ s <= arr))%Z.
Hypothesis SOKa : store_ok SEGS M0 (Z_to_bv 64 arr) (Z.to_nat (4 * n)) = true.
Hypothesis SOKs : store_ok SEGS M0 (Z_to_bv 64 (s - 272 - 16)) 16 = true.
Ltac geo := pose proof GEO as (Gs & Gs47 & Ga & Ga2 & Gn & AP).

Definition CL_SpL : list reg := [1; 2; 8; 9; 10; 11; 12]%bv.
Lemma SpL_loop : forall (j : nat) fr0 regs0 fr cs regs (M : word -> option byte) (i : Z),
  Z.of_nat j = (n - i)%Z -> (0 <= i < n)%Z -> frm_zero cs -> rinv R_SpL M0 M ->
  getr regs 2 = Z_to_bv 64 (s - 272) -> getr regs 8 = Z_to_bv 64 i -> getr regs 9 = Z_to_bv 64 (arr + 4 * i) -> getr regs 18 = Z_to_bv 64 n ->
  regs_agree (fun r => In r CL_SpL) regs0 regs -> (forall r : reg, In (u r) fs_list -> reg_get fr r = reg_get fr0 r) ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2db30 : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2db54 : word) M' rom /\ frm_zero cs' /\ rinv R_SpL M0 M' /\
                getr regs' 2 = Z_to_bv 64 (s - 272) /\ regs_agree (fun r => In r CL_SpL) regs0 regs' /\
                (forall r : reg, In (u r) fs_list -> reg_get fr' r = reg_get fr0 r)).
Proof.
