Definition HJL : list reg := [5; 6; 7; 17; 28; 29]%bv.
(* [comment removed for export] *)
Lemma hj_body : forall fr0 regs0 fr cs regs (M : word -> option byte) (W spat rng kval rb col rt dcol j wend : Z),
  frm_zero cs ->
  (rb mod 4 = 0)%Z -> (W mod 4 = 0)%Z -> (4096 <= rb)%Z -> (rb + W <= 2 ^ 47)%Z -> (0 <= col)%Z -> (col + 20 < W)%Z ->
  (rt mod 4 = 0)%Z -> (4096 <= rt)%Z -> (rt + W <= 2 ^ 47)%Z -> (0 <= dcol < W)%Z -> (0 <= j < 2 ^ 31)%Z -> (0 <= wend)%Z -> (wend + j = rb + col + 21)%Z ->
  (4096 <= spat)%Z -> (spat + 44 <= 2 ^ 47)%Z -> (4096 <= rng)%Z -> (rng + 1024 <= 2 ^ 47)%Z -> (0 <= kval <= 255)%Z ->
  (forall p, (rb <= p < rb + W)%Z -> exists b, rdn SEGS M (Z_to_bv 64 p) 1 = Some [b]) ->
  (forall q, (0 <= q <= 10)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (spat + 4 * q)) 4 = Some bs) ->
  (forall d, (0 <= d <= 255)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (rng + 4 * d)) 4 = Some bs) ->
  (forall p, (rt <= p < rt + W)%Z -> store_ok SEGS M (Z_to_bv 64 p) 1 = true) ->
  getr regs 13 = Z_to_bv 64 j -> getr regs 14 = Z_to_bv 64 wend -> getr regs 15 = Z_to_bv 64 (rt + dcol - j) -> getr regs 16 = Z_to_bv 64 (rb + col) ->
  getr regs 18 = Z_to_bv 64 (-10) -> getr regs 25 = Z_to_bv 64 10 -> getr regs 9 = Z_to_bv 64 0x12ce0 ->
  getr regs 23 = Z_to_bv 64 spat -> getr regs 24 = Z_to_bv 64 rng -> getr regs 26 = Z_to_bv 64 kval ->
  regs_agree (fun r => In r HJL) regs0 regs -> hc_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2dd40 : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2dd34 : word) M' rom /\ frm_zero cs' /\
                (M' = M \/ exists p bs, (rt <= p < rt + W)%Z /\ length bs = 1%nat /\ M' = wbytes M (Z_to_bv 64 p) bs) /\
                regs_agree (fun r => In r HJL) regs0 regs' /\ hc_fp fr0 fr').
Proof.
