#[local] Instance bil_fxd : FPState | 100 := mkFP bvmap_empty (Z_to_bv 32 0).

Definition HJL2 : list reg := [5; 6; 7; 13; 16; 17; 28; 29]%bv.
(* [comment removed for export] *)
Lemma hj_loop : forall (n : nat) fr0 regs0 fr cs regs (Mj M : word -> option byte) (W spat rng kval rb rt wd j : Z),
  Z.of_nat n = (wd - j)%Z -> (0 <= j < wd)%Z -> (wd + 22 <= W)%Z -> (W <= 80000)%Z -> frm_zero cs -> rinv [(rt, W)] Mj M ->
  (rb mod 4 = 0)%Z -> (W mod 4 = 0)%Z -> (4096 <= rb)%Z -> (rb + W <= 2 ^ 47)%Z -> (rt mod 4 = 0)%Z -> (4096 <= rt)%Z -> (rt + W <= 2 ^ 47)%Z ->
  (4096 <= spat)%Z -> (spat + 44 <= 2 ^ 47)%Z -> (4096 <= rng)%Z -> (rng + 1024 <= 2 ^ 47)%Z -> (0 <= kval <= 255)%Z ->
  store_ok SEGS Mj (Z_to_bv 64 rb) (Z.to_nat W) = true -> store_ok SEGS Mj (Z_to_bv 64 rt) (Z.to_nat W) = true ->
  store_ok SEGS Mj (Z_to_bv 64 spat) 44 = true -> store_ok SEGS Mj (Z_to_bv 64 rng) 1024 = true ->
  getr regs 13 = Z_to_bv 64 j -> getr regs 14 = Z_to_bv 64 (rb + 22) -> getr regs 15 = Z_to_bv 64 (rt + 11) -> getr regs 16 = Z_to_bv 64 (rb + 1 + j) ->
  getr regs 22 = Z_to_bv 64 wd -> getr regs 18 = Z_to_bv 64 (-10) -> getr regs 25 = Z_to_bv 64 10 -> getr regs 9 = Z_to_bv 64 0x12ce0 ->
  getr regs 23 = Z_to_bv 64 spat -> getr regs 24 = Z_to_bv 64 rng -> getr regs 26 = Z_to_bv 64 kval ->
  regs_agree (fun r => In r HJL2) regs0 regs -> hc_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2dd40 : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2dd00 : word) M' rom /\ frm_zero cs' /\ rinv [(rt, W)] Mj M' /\
                regs_agree (fun r => In r HJL2) regs0 regs' /\ hc_fp fr0 fr').
Proof.
