Definition HIL : list reg := [5; 6; 7; 10; 12; 13; 14; 15; 16; 17; 28; 29]%bv.
(* [comment removed for export] *)
Lemma hi_loop : forall (n : nat) fr0 regs0 fr cs regs (M0 M : word -> option byte) (W wpl datas datat hs wd hd spat rng kval i : Z),
  Z.of_nat n = (hd - i)%Z -> (0 <= i < hd)%Z -> (hd + 22 <= hs)%Z -> (hs <= 20000)%Z -> (1 <= wd)%Z -> (wd + 22 <= W)%Z -> (W = 4 * wpl)%Z -> (W <= 80000)%Z ->
  frm_zero cs -> rinv [(datat, (W * hs)%Z)] M0 M ->
  (datas mod 4 = 0)%Z -> (4096 <= datas)%Z -> (datas + W * hs <= 2 ^ 47)%Z -> (datat mod 4 = 0)%Z -> (4096 <= datat)%Z -> (datat + W * hs <= 2 ^ 47)%Z ->
  (4096 <= spat)%Z -> (spat + 44 <= 2 ^ 47)%Z -> (4096 <= rng)%Z -> (rng + 1024 <= 2 ^ 47)%Z -> (0 <= kval <= 255)%Z ->
  store_ok SEGS M0 (Z_to_bv 64 datas) (Z.to_nat (W * hs)) = true -> store_ok SEGS M0 (Z_to_bv 64 datat) (Z.to_nat (W * hs)) = true ->
  store_ok SEGS M0 (Z_to_bv 64 spat) 44 = true -> store_ok SEGS M0 (Z_to_bv 64 rng) 1024 = true ->
  getr regs 10 = Z_to_bv 64 i -> getr regs 11 = Z_to_bv 64 (datat + 11) -> getr regs 12 = Z_to_bv 64 (datas + 11 * W + 1 + W * i) ->
  getr regs 19 = Z_to_bv 64 W -> getr regs 27 = Z_to_bv 64 wpl -> getr regs 30 = Z_to_bv 64 11 -> getr regs 31 = Z_to_bv 64 (datas + 11 * W + 22) ->
  getr regs 21 = Z_to_bv 64 hd -> getr regs 22 = Z_to_bv 64 wd -> getr regs 18 = Z_to_bv 64 (-10) -> getr regs 25 = Z_to_bv 64 10 ->
  getr regs 9 = Z_to_bv 64 0x12ce0 -> getr regs 23 = Z_to_bv 64 spat -> getr regs 24 = Z_to_bv 64 rng -> getr regs 26 = Z_to_bv 64 kval ->
  regs_agree (fun r => In r HIL) regs0 regs -> hc_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2dd0c : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2dde0 : word) M' rom /\ frm_zero cs' /\ rinv [(datat, (W * hs)%Z)] M0 M' /\
                regs_agree (fun r => In r HIL) regs0 regs' /\ hc_fp fr0 fr').
