(* [comment removed for export] *)
Definition VKL : list reg := [5; 6; 7; 28; 29; 30]%bv.

(* [comment removed for export] *)
Lemma vk_loop : forall (n : nat) fr0 regs0 fr cs regs (M : word -> option byte) (W Wh dt spat rng kval c cur : Z),
  Z.of_nat n = c -> (1 <= c <= 21)%Z -> frm_zero cs ->
  (dt mod 4 = 0)%Z -> (Wh mod 4 = 0)%Z -> (4096 <= dt)%Z -> (dt + Wh <= 2 ^ 47)%Z -> (0 <= W <= 80000)%Z -> (dt <= cur)%Z -> (cur + W * (c - 1) < dt + Wh)%Z ->
  (4096 <= spat)%Z -> (spat + 44 <= 2 ^ 47)%Z -> (4096 <= rng)%Z -> (rng + 1024 <= 2 ^ 47)%Z -> (0 <= kval <= 255)%Z ->
  (forall p, (dt <= p < dt + Wh)%Z -> exists b, rdn SEGS M (Z_to_bv 64 p) 1 = Some [b]) ->
  (forall q, (0 <= q <= 10)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (spat + 4 * q)) 4 = Some bs) ->
  (forall d, (0 <= d <= 255)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (rng + 4 * d)) 4 = Some bs) ->
  getr regs 5 = Z_to_bv 64 c -> getr regs 6 = Z_to_bv 64 (11 - c) -> getr regs 7 = Z_to_bv 64 cur -> getr regs 12 = Z_to_bv 64 W ->
  getr regs 23 = Z_to_bv 64 spat -> getr regs 24 = Z_to_bv 64 rng -> getr regs 26 = Z_to_bv 64 kval ->
  regs_agree (fun r => In r VKL) regs0 regs -> hc_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2debc : word) M rom)
    (fun fin => exists fr' cs' regs', fin = @mkst (mkFP fr' cs') regs' (0x2df1c : word) M rom /\ frm_zero cs' /\
                regs_agree (fun r => In r VKL) regs0 regs' /\ hc_fp fr0 fr').
Proof.
