Definition VJL : list reg := [5; 6; 7; 14; 17; 28; 29; 30]%bv.
(* [comment removed for export] *)
Lemma vj_store : forall fr cs regs (M : word -> option byte) (Wd rd j cur0 : Z),
  (rd mod 4 = 0)%Z -> (Wd mod 4 = 0)%Z -> (4096 <= rd)%Z -> (rd + Wd <= 2 ^ 47)%Z -> (0 <= j < Wd)%Z -> (0 <= cur0 < 2 ^ 47)%Z ->
  (forall p, (rd <= p < rd + Wd)%Z -> store_ok SEGS M (Z_to_bv 64 p) 1 = true) ->
