(* [comment removed for export] *)
Lemma vj_body : forall fr0 regs0 fr cs regs (M : word -> option byte) (W Wh dt Wd rd tb spat rng kval j cur0 : Z),
  frm_zero cs ->
  (dt mod 4 = 0)%Z -> (Wh mod 4 = 0)%Z -> (4096 <= dt)%Z -> (dt + Wh <= 2 ^ 47)%Z -> (0 <= W <= 80000)%Z -> (dt <= cur0)%Z -> (cur0 + W * 20 < dt + Wh)%Z ->
  (dt <= tb + j < dt + Wh)%Z ->
  (rd mod 4 = 0)%Z -> (Wd mod 4 = 0)%Z -> (4096 <= rd)%Z -> (rd + Wd <= 2 ^ 47)%Z -> (0 <= j < Wd)%Z ->
  (4096 <= spat)%Z -> (spat + 44 <= 2 ^ 47)%Z -> (4096 <= rng)%Z -> (rng + 1024 <= 2 ^ 47)%Z -> (0 <= kval <= 255)%Z ->
  (forall p, (dt <= p < dt + Wh)%Z -> exists b, rdn SEGS M (Z_to_bv 64 p) 1 = Some [b]) ->
  (forall q, (0 <= q <= 10)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (spat + 4 * q)) 4 = Some bs) ->
  (forall d, (0 <= d <= 255)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (rng + 4 * d)) 4 = Some bs) ->
  (forall p, (rd <= p < rd + Wd)%Z -> store_ok SEGS M (Z_to_bv 64 p) 1 = true) ->
  getr regs 14 = Z_to_bv 64 j -> getr regs 15 = Z_to_bv 64 rd -> getr regs 16 = Z_to_bv 64 tb -> getr regs 17 = Z_to_bv 64 cur0 -> getr regs 12 = Z_to_bv 64 W ->
  getr regs 20 = Z_to_bv 64 21 -> getr regs 18 = Z_to_bv 64 (-10) -> getr regs 25 = Z_to_bv 64 10 -> getr regs 9 = Z_to_bv 64 0x12ce0 ->
  getr regs 23 = Z_to_bv 64 spat -> getr regs 24 = Z_to_bv 64 rng -> getr regs 26 = Z_to_bv 64 kval ->
  regs_agree (fun r => In r VJL) regs0 regs -> hc_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2dea4 : word) M rom)
    (fun fin => exists fr' cs' regs' p bs, fin = @mkst (mkFP fr' cs') regs' (0x2dea0 : word) (wbytes M (Z_to_bv 64 p) bs) rom /\ frm_zero cs' /\
                (rd <= p < rd + Wd)%Z /\ length bs = 1%nat /\ getr regs' 14 = Z_to_bv 64 (j + 1) /\ getr regs' 17 = Z_to_bv 64 (cur0 + 1) /\
