Definition VIL : list reg := [5; 6; 7; 11; 13; 14; 15; 16; 17; 28; 29; 30]%bv.
(* [comment removed for export] *)
Lemma vi_loop : forall (n : nat) fr0 regs0 fr cs regs (M0 M : word -> option byte) (W wpl datat hs Wd wpld datad wd hd spat rng kval i : Z),
  Z.of_nat n = (hd - i)%Z -> (0 <= i < hd)%Z -> (hd + 22 <= hs)%Z -> (hs <= 20000)%Z -> (1 <= wd)%Z -> (wd + 22 <= W)%Z -> (W = 4 * wpl)%Z -> (W <= 80000)%Z ->
  (wd <= Wd)%Z -> (wd <= 20000)%Z -> (Wd = 4 * wpld)%Z -> (Wd <= 80000)%Z -> frm_zero cs -> rinv [(datad, (Wd * hd)%Z)] M0 M ->
  (datat mod 4 = 0)%Z -> (4096 <= datat)%Z -> (datat + W * hs <= 2 ^ 47)%Z -> (datad mod 4 = 0)%Z -> (4096 <= datad)%Z -> (datad + Wd * hd <= 2 ^ 47)%Z ->
  (4096 <= spat)%Z -> (spat + 44 <= 2 ^ 47)%Z -> (4096 <= rng)%Z -> (rng + 1024 <= 2 ^ 47)%Z -> (0 <= kval <= 255)%Z ->
  store_ok SEGS M0 (Z_to_bv 64 datat) (Z.to_nat (W * hs)) = true -> store_ok SEGS M0 (Z_to_bv 64 datad) (Z.to_nat (Wd * hd)) = true ->
  store_ok SEGS M0 (Z_to_bv 64 spat) 44 = true -> store_ok SEGS M0 (Z_to_bv 64 rng) 1024 = true ->
  getr regs 10 = Z_to_bv 64 wpld -> getr regs 11 = Z_to_bv 64 i -> getr regs 12 = Z_to_bv 64 W -> getr regs 13 = Z_to_bv 64 (datat + W + 11 + W * i) ->
  getr regs 8 = Z_to_bv 64 datad -> getr regs 1 = Z_to_bv 64 datat -> getr regs 31 = Z_to_bv 64 11 -> getr regs 27 = Z_to_bv 64 wpl ->
  getr regs 21 = Z_to_bv 64 hd -> getr regs 22 = Z_to_bv 64 wd -> getr regs 20 = Z_to_bv 64 21 -> getr regs 18 = Z_to_bv 64 (-10) -> getr regs 25 = Z_to_bv 64 10 ->
  getr regs 9 = Z_to_bv 64 0x12ce0 -> getr regs 23 = Z_to_bv 64 spat -> getr regs 24 = Z_to_bv 64 rng -> getr regs 26 = Z_to_bv 64 kval ->
  regs_agree (fun r => In r VIL) regs0 regs -> hc_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2de50 : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2dc7c : word) M' rom /\ frm_zero cs' /\ rinv [(datad, (Wd * hd)%Z)] M0 M' /\
                regs_agree (fun r => In r VIL) regs0 regs' /\ hc_fp fr0 fr').
